public String readString() throws IOException {
    // Check if the input stream is null or empty
    if (this.input == null || this.input.available() <= 0) {
        throw new IOException("Input stream is null or empty");
    }

    // Read the next byte from the input stream
    int b = this.input.readByte();

    // Check if the byte is a valid start byte (0x00)
    if (b != 0) {
        throw new IOException("Invalid start byte: " + b);
    }

    // Read the next two bytes from the input stream
    int length = this.input.readUnsignedShort();
    byte[] buffer = new byte[length];

    // Check if the next bytes are a valid length (greater than 0 and less than the maximum allowed value)
    if (length <= 0 || length > Short.MAX_VALUE) {
        throw new IOException("Invalid length: " + length);
    }

    // Check if the buffer is large enough to contain the string bytes
    if (buffer.length < length) {
        throw new IOException("Buffer is too small to contain the string bytes");
    }

    // Read the bytes from the input stream
    int i = 0;
    int remaining = length;
    while (remaining > 0) {
        int bytesRead = this.input.read(buffer, i, remaining);
        if (bytesRead < 0) {
            throw new IOException("Unexpected EOF while reading the string");
        }
        i += bytesRead;
        remaining -= bytesRead;
    }

    // Check if the last byte read is a null byte (0x00)
    if (buffer[length - 1] != 0) {
        throw new IOException("Invalid null byte at the end of the string");
    }

    // Return the decoded string
    return new String(buffer, 0, length - 1, "UTF-8");
}

